<div class="d-flex align-items-center gap-2"><label for="period" class="small">{{ $t['period'] }}</label><select id="period" class="form-select form-select-sm" style="min-width:115px"><option value="7">{{ $t['days7'] }}</option><option value="30" selected>{{ $t['days30'] }}</option><option value="90">{{ $t['days90'] }}</option></select><button id="refresh" class="btn btn-sm btn-light">{{ $t['refresh'] }}</button></div>
