</div>
<section class="panel p-3 p-lg-4"><div class="d-flex justify-content-between align-items-center flex-wrap gap-2 mb-3"><h2 class="h6 fw-bold mb-0">{{ $t['fastest'] }}</h2><span class="muted" id="meta"></span></div>
<div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>{{ $t['index'] }}</th><th class="text-end">{{ $t['docs'] }}</th><th class="text-end">{{ $t['storageSize'] }}</th><th class="text-end">{{ $t['storageGrowth'] }}</th><th class="text-end">{{ $t['docGrowth'] }}</th></tr></thead><tbody id="indices"><tr><td colspan="5" class="text-center text-secondary py-4">{{ $t['loading'] }}</td></tr></tbody></table></div></section>
<p class="muted mt-3" id="updated"></p>
</main>
<script>
const endpoint=@json(route('elasticsearch-monitoring.capacity.data',['locale'=>$locale]));const t=@json($t);let charts={};
const number=v=>Number(v||0).toLocaleString();const bytes=v=>{v=Number(v||0);if(v<1)return '0 B';const u=['B','KB','MB','GB','TB','PB'];const i=Math.min(Math.floor(Math.log(v)/Math.log(1024)),u.length-1);return (v/Math.pow(1024,i)).toFixed(i>2?2:1)+' '+u[i];};
function chart(id,series,formatter){if(charts[id])charts[id].destroy();charts[id]=new ApexCharts(document.querySelector('#'+id),{chart:{type:'line',height:260,toolbar:{show:false},animations:{enabled:false}},series,stroke:{curve:'smooth',width:2},dataLabels:{enabled:false},xaxis:{type:'datetime'},yaxis:{labels:{formatter}},legend:{position:'top'},noData:{text:t.unavailable}});charts[id].render();}
function render(d){const s=d.summary||{},g=s.storage_growth_bytes;const cards=[[t.documents,number(s.documents)],[t.storage,bytes(s.storage_bytes)],[t.disk,bytes(s.filesystem_used_bytes)],[t.growth,g===null?t.unavailable:(g>=0?'+':'')+bytes(g)]];
document.getElementById('metrics').innerHTML=cards.map(c=>'<div class="col-6 col-xl-3"><div class="panel metric"><div class="label">'+c[0]+'</div><div class="value">'+c[1]+'</div></div></div>').join('');
const h=d.history||[];chart('storage-chart',[{name:t.storage,data:h.map(p=>[new Date(p.collected_at).getTime(),p.storage_bytes])}],v=>bytes(v));chart('documents-chart',[{name:t.documents,data:h.map(p=>[new Date(p.collected_at).getTime(),p.documents])}],v=>number(v));
chart('disk-chart',(d.nodes||[]).map(n=>({name:n.name,data:(n.history||[]).map(p=>[new Date(p.collected_at).getTime(),p.used_percent])})),v=>v===null?'—':v.toFixed(1)+'%');
document.getElementById('forecast-list').innerHTML=(d.nodes||[]).map(n=>{const f=n.forecast;if(!f)return '<div class="col-12"><div class="forecast">'+n.name+' · '+t.insufficient+'</div></div>';const remaining=f.days_to_full===null?t.noGrowth:number(f.days_to_full)+' '+t.days;return '<div class="col-12 col-md-6"><div class="forecast"><strong>'+n.name+'</strong><div class="muted mt-1">'+t.remaining+'</div><div class="fs-5 fw-bold">'+remaining+'</div><div class="muted">'+t.growthDay+': '+bytes(f.growth_bytes_per_day)+'</div><div class="muted">'+t.confidence+': '+t[f.confidence]+'</div></div></div>';}).join('')||'<div class="col-12 muted">'+t.empty+'</div>';
const ix=d.fastest_indices||[];document.getElementById('indices').innerHTML=ix.length?ix.map(i=>'<tr><td class="fw-semibold">'+i.name+'</td><td class="text-end">'+number(i.documents)+'</td><td class="text-end">'+bytes(i.storage_bytes)+'</td><td class="text-end">'+(i.storage_growth_per_day>=0?'+':'')+bytes(i.storage_growth_per_day)+'</td><td class="text-end">'+number(i.document_growth_per_day)+'</td></tr>').join(''):'<tr><td colspan="5" class="text-center text-secondary py-4">'+t.empty+'</td></tr>';
document.getElementById('meta').textContent=number(d.meta?.snapshots)+' '+t.samples+' · '+t.retention+': '+number(d.meta?.retention_days)+' '+t.days;document.getElementById('updated').textContent=t.updated+': '+(d.meta?.latest_collected_at?new Date(d.meta.latest_collected_at).toLocaleString():t.unavailable);}
async function load(){document.getElementById('metrics').innerHTML='<div class="col-12 text-secondary">'+t.loading+'</div>';try{const r=await fetch(endpoint+'&days='+document.getElementById('period').value,{headers:{Accept:'application/json'}});if(!r.ok)throw new Error();render(await r.json());}catch(e){document.getElementById('metrics').innerHTML='<div class="col-12 text-danger">'+t.error+'</div>';}}
document.getElementById('refresh').addEventListener('click',load);document.getElementById('period').addEventListener('change',load);load();setInterval(load,60000);
</script>
</body></html>
